// index.js
require('dotenv').config();

const crawler = require('./crawler');
const postCron = require('./postCron');

const {
  Client,
  GatewayIntentBits,
  Partials,
  Events,
} = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
  partials: [
    Partials.Channel,
  ],
});

client.once(Events.ClientReady, () => {
  console.log('Ready!');
  postCron(client).start();
});

client.on(Events.InteractionCreate, async (interaction) => {
  if (interaction.commandName === 'blog') {
    const data = await crawler();
    const randomIndex = Math.floor(Math.random() * data.length);
    const randomData = data[randomIndex];
    await interaction.reply(`Random recommendation from Ray: [${randomData.title}](${randomData.url})`);
  }
});

client.login(process.env.DISCORD_TOKEN);

// postCron.js
const cron = require('cron');

const crawler = require('./crawler'); // Import scraper

const postCron = (client) => {
  const job = new cron.CronJob('* * * * *', async () => {
    // Call scraper and get data
    const data = await crawler();
    // Generate a random index
    const randomIndex = Math.floor(Math.random() * data.length);
    // Get the random data
    const randomData = data[randomIndex];
    // Get the channel
    const channel = client.channels.cache.get(process.env.DISCORD_CHANNEL_ID);
    // Send message
    await channel.send(`Daily 9 PM random recommendation from Ray: [${randomData.title}](${randomData.url})`);
  });

  return job;
}


module.exports = postCron;

// crawler.js
const cheerio = require('cheerio');

const getData = async (url) => {
  try {
    const response = await fetch(url);
    const data = await response.text();
    return data;
  } catch (error) {
    console.log(error);
  }
}

const crawler = async () => {
  const target = 'https://israynotarray.com/'; // Target URL
  const html = await getData(target);

  const $ = cheerio.load(html);

  const postTitleLink = $('.post-title-link');

  const data = [];

  postTitleLink.each((index, element) => {
    const title = $(element).text();
    const url = $(element).attr('href');
    data.push({
      title,
      url: `${target}${url}`, // Append the domain
    });
  });

  return data;
}

module.exports = crawler;

// register.js
require('dotenv').config(); // Import dotenv

const {
  REST,
  Routes
} = require('discord.js');

const list = [
  {
    name: 'blog',
    description: 'Get a random article from the homepage',
  },
];

const rest = new REST({ version: '10' }).setToken(process.env.DISCORD_TOKEN);

const registerCommands = async (commands) => {
  try {
    console.log('Started refreshing application (/) commands.');

    await rest.put(Routes.applicationCommands(process.env.DISCORD_CLIENT_ID), { body: commands });

    console.log('Successfully reloaded application (/) commands.');
  } catch (error) {
    console.error(error);
  }
}

registerCommands(list)

